double TransportAI::Unload(FEconomyState& State, Ship& Freighter, FName Destination,
    double Limit)
{
    if (!FMath::IsFinite(Limit) || Limit <= 0 || !Freighter.GetCargoManifest()) return
    0;
    Freighter.SyncCargoInventory();
    const auto* To = State.Inventories.Find(Destination);
    if (!To) return 0;
    const double Amount = FMath::Min3(Freighter.GetMinedOreTonnes(), Limit,
    FMath::Max(0.0, To->CapacityTonnes - FEconomyLedger::Used(*To)));
    if (Amount <= 0 || !FEconomyLedger::Transfer(State,
    FEconomyRuntime::IndustryOwner(), Freighter.GetCargoInventoryKey(), Destination,
        DataTableUtils::MakeValidName(Freighter.GetCargoManifest()->Item), Amount))
    return 0;
    return Freighter.UnloadMinedOre(Amount, false);
}
